  "root_causes": [
    {
      "service": "cart",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT max(time) AS last_cart_span_normal, (SELECT count(*) FROM abnormal_traces WHERE service_name='cart') AS abnormal_cart_spans FROM normal_traces WHERE service_name='cart'",
          "claim": "Cart emits spans normally until 10:38:11, then produces zero spans in the abnormal window."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, min(value) AS cpu_min, max(value) AS cpu_max, count(*) AS n FROM abnormal_metrics_sum WHERE metric='container.cpu.time' AND attr_k8s_pod_name LIKE 'cart%' GROUP BY 1",
          "claim": "Cart container CPU counter stays flat near 0.0126 through the abnormal window, versus about 12 in normal."
        },
        {
          "kind": "metric",
          "sql": "SELECT attr_k8s_pod_name AS pod, min(value) AS uptime_min, max(value) AS uptime_max FROM abnormal_metrics_sum WHERE metric='k8s.pod.uptime' AND attr_k8s_pod_name LIKE 'cart%' GROUP BY 1",
          "claim": "Cart pod uptime continues monotonically (about 3546 to 3766 s) with no reset, so the pod did not restart."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "cart",
      "to": "checkout",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n, round(avg(duration)/1e6,2) AS avg_ms FROM abnormal_traces WHERE service_name='checkout' AND attr_span_kind='Client' GROUP BY 1,2",
          "claim": "All 22 checkout calls to CartService/GetCart fail in about 0.14 ms, with no callee spans."
        }
      ]
    },
    {
      "from": "cart",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name LIKE '%CartService%' GROUP BY 1,2",
          "claim": "Frontend's CartService AddItem and GetCart client calls fail in the abnormal window (71 and 35 errors)."
        }
      ]
    },
    {
      "from": "checkout",
      "to": "frontend",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_status_code, count(*) AS n FROM abnormal_traces WHERE service_name='frontend' AND attr_span_kind='Client' AND span_name LIKE '%CheckoutService%' GROUP BY 1,2",
          "claim": "All 22 frontend calls to CheckoutService/PlaceOrder return errors, matching checkout's failing PlaceOrder server spans."
        }
      ]
    },
    {
      "from": "frontend",
      "to": "frontend-proxy",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, attr_span_kind, count(*) AS n, avg(CASE WHEN attr_status_code='Error' THEN 1 ELSE 0 END) AS err_share FROM abnormal_traces WHERE service_name IN ('frontend','frontend-proxy') AND attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Frontend-proxy server error share rises to about 0.39, matching frontend's 0.40 server error share."
        }
      ]
    }
  ]
}
```

